import { z } from "zod";

export const COMMS_STATUSES = ["INFO", "ASK", "BLOCKED", "HANDOFF", "DONE"] as const;

export type CommsStatus = (typeof COMMS_STATUSES)[number];

export const CommsStatusSchema = z.enum(COMMS_STATUSES);

const AGENT_NAME_MAX = 64;
const BODY_MAX = 16_000;
const TASK_ID_MAX = 128;

const AgentNameSchema = z
  .string()
  .trim()
  .min(1)
  .max(AGENT_NAME_MAX)
  .regex(/^[A-Za-z][A-Za-z0-9 ._-]*$/, "Invalid agent name");

export const CommsMessageSchema = z.object({
  ts: z.string().datetime(),
  author: AgentNameSchema,
  recipient: AgentNameSchema,
  task_id: z.string().trim().min(1).max(TASK_ID_MAX).optional(),
  status: CommsStatusSchema,
  body: z.string().trim().min(1).max(BODY_MAX),
});

export type CommsMessage = z.infer<typeof CommsMessageSchema>;

export const CommsPostInputSchema = z.object({
  author: AgentNameSchema,
  recipient: AgentNameSchema,
  task_id: z.string().trim().min(1).max(TASK_ID_MAX).optional(),
  status: CommsStatusSchema,
  body: z.string().trim().min(1).max(BODY_MAX),
});

export type CommsPostInput = z.infer<typeof CommsPostInputSchema>;

export const CommsReadFilterSchema = z.object({
  task_id: z.string().trim().min(1).max(TASK_ID_MAX).optional(),
  since: z.string().datetime().optional(),
  limit: z.coerce.number().int().min(1).max(500).optional(),
});

export type CommsReadFilter = z.infer<typeof CommsReadFilterSchema>;

export const COMMS_JSONL_FILE = "comms.jsonl";
export const COMMS_MARKDOWN_RELATIVE = "COMMS-CLAUDE-GROK.md";

export function formatCommsMarkdownStamp(isoTimestamp: string): string {
  const date = new Date(isoTimestamp);
  if (Number.isNaN(date.getTime())) {
    throw new Error("Invalid ISO timestamp for comms markdown stamp");
  }
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, "0");
  const d = String(date.getDate()).padStart(2, "0");
  const h = String(date.getHours()).padStart(2, "0");
  const min = String(date.getMinutes()).padStart(2, "0");
  return `${y}-${m}-${d} ${h}:${min}`;
}

export function formatCommsMarkdownEntry(message: CommsMessage): string {
  const stamp = formatCommsMarkdownStamp(message.ts);
  const header = `### [${stamp}] ${message.author} → ${message.recipient} · [${message.status}]`;
  return `${header}\n\n${message.body}\n\n---\n`;
}

import { appendFile, mkdir, readFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import {
  CommsMessageSchema,
  CommsPostInputSchema,
  CommsReadFilterSchema,
  formatCommsMarkdownEntry,
  COMMS_JSONL_FILE,
  COMMS_MARKDOWN_RELATIVE,
  type CommsMessage,
  type CommsPostInput,
  type CommsReadFilter,
} from "../../shared/src/comms.js";

export interface CommsPostResult {
  message: CommsMessage;
}

export interface CommsReadResult {
  messages: CommsMessage[];
  skipped_invalid_lines: number;
}

export class CommsService {
  private readonly jsonlPath: string;
  private readonly markdownPath: string;

  constructor(janusRoot: string, stateDir = ".aether") {
    this.jsonlPath = join(janusRoot, stateDir, COMMS_JSONL_FILE);
    this.markdownPath = join(janusRoot, COMMS_MARKDOWN_RELATIVE);
  }

  async post(input: CommsPostInput): Promise<CommsPostResult> {
    const parsed = CommsPostInputSchema.parse(input);
    const message: CommsMessage = CommsMessageSchema.parse({
      ts: new Date().toISOString(),
      ...parsed,
    });

    await mkdir(dirname(this.jsonlPath), { recursive: true });
    await appendFile(this.jsonlPath, `${JSON.stringify(message)}\n`, "utf8");
    await appendFile(this.markdownPath, `\n${formatCommsMarkdownEntry(message)}`, "utf8");

    return { message };
  }

  async read(filter: CommsReadFilter = {}): Promise<CommsReadResult> {
    const parsed = CommsReadFilterSchema.parse(filter);
    let raw = "";
    try {
      raw = await readFile(this.jsonlPath, "utf8");
    } catch (error) {
      if (isEnoent(error)) {
        return { messages: [], skipped_invalid_lines: 0 };
      }
      throw error;
    }

    const messages: CommsMessage[] = [];
    let skipped = 0;
    const sinceMs =
      parsed.since !== undefined ? new Date(parsed.since).getTime() : undefined;

    for (const line of raw.split(/\r?\n/)) {
      const trimmed = line.trim();
      if (!trimmed) {
        continue;
      }

      let record: unknown;
      try {
        record = JSON.parse(trimmed);
      } catch {
        skipped += 1;
        continue;
      }

      const parsedMessage = CommsMessageSchema.safeParse(record);
      if (!parsedMessage.success) {
        skipped += 1;
        continue;
      }

      const msg = parsedMessage.data;
      if (parsed.task_id !== undefined && msg.task_id !== parsed.task_id) {
        continue;
      }

      if (sinceMs !== undefined) {
        const msgMs = new Date(msg.ts).getTime();
        if (Number.isNaN(msgMs) || msgMs < sinceMs) {
          continue;
        }
      }

      messages.push(msg);
    }

    messages.sort((a, b) => a.ts.localeCompare(b.ts));

    const limit = parsed.limit ?? 100;
    const sliced = messages.length > limit ? messages.slice(-limit) : messages;

    return { messages: sliced, skipped_invalid_lines: skipped };
  }
}

function isEnoent(error: unknown): boolean {
  return (
    typeof error === "object" &&
    error !== null &&
    "code" in error &&
    (error as { code: string }).code === "ENOENT"
  );
}

import { mkdtemp, readFile, rm } from "node:fs/promises";
import { join } from "node:path";
import { tmpdir } from "node:os";
import { afterEach, describe, expect, it } from "vitest";
import { CommsService } from "./comms-service.js";

describe("CommsService", () => {
  const roots: string[] = [];

  afterEach(async () => {
    await Promise.all(roots.splice(0).map((root) => rm(root, { recursive: true, force: true })));
  });

  async function createService(): Promise<{ service: CommsService; root: string }> {
    const root = await mkdtemp(join(tmpdir(), "janus-comms-"));
    roots.push(root);
    return { service: new CommsService(root), root };
  }

  it("appends messages to jsonl and mirrors markdown", async () => {
    const { service, root } = await createService();

    const posted = await service.post({
      author: "Grok",
      recipient: "Claude",
      task_id: "task-test-1",
      status: "INFO",
      body: "Round-trip probe",
    });

    const jsonl = await readFile(join(root, ".aether", "comms.jsonl"), "utf8");
    expect(jsonl.trim()).toContain("Round-trip probe");
    expect(jsonl.trim()).toContain("task-test-1");

    const markdown = await readFile(join(root, "COMMS-CLAUDE-GROK.md"), "utf8");
    expect(markdown).toContain("Grok → Claude");
    expect(markdown).toContain("[INFO]");
    expect(markdown).toContain("Round-trip probe");

    const readBack = await service.read({ task_id: "task-test-1" });
    expect(readBack.messages).toHaveLength(1);
    expect(readBack.messages[0]?.body).toBe("Round-trip probe");
    expect(readBack.messages[0]?.ts).toBe(posted.message.ts);
  });

  it("filters by since timestamp", async () => {
    const { service } = await createService();

    await service.post({
      author: "Claude",
      recipient: "Grok",
      status: "HANDOFF",
      body: "Earlier",
    });

    const firstRead = await service.read();
    const firstTs = firstRead.messages[0]?.ts;
    expect(firstTs).toBeTruthy();

    await new Promise((resolve) => setTimeout(resolve, 5));

    await service.post({
      author: "Grok",
      recipient: "Claude",
      status: "DONE",
      body: "Later",
    });

    const filtered = await service.read({ since: firstTs });
    expect(filtered.messages.length).toBeGreaterThanOrEqual(1);
    expect(filtered.messages.every((msg) => msg.ts >= firstTs!)).toBe(true);
    expect(filtered.messages.some((msg) => msg.body === "Later")).toBe(true);
  });

  it("returns empty list when store is missing", async () => {
    const { service } = await createService();
    const result = await service.read();
    expect(result.messages).toEqual([]);
    expect(result.skipped_invalid_lines).toBe(0);
  });

  it("skips invalid jsonl lines", async () => {
    const { service, root } = await createService();
    await service.post({
      author: "Grok",
      recipient: "Claude",
      status: "INFO",
      body: "Valid line",
    });

    const jsonlPath = join(root, ".aether", "comms.jsonl");
    const { appendFile } = await import("node:fs/promises");
    await appendFile(jsonlPath, "not-json\n", "utf8");

    const result = await service.read();
    expect(result.messages).toHaveLength(1);
    expect(result.skipped_invalid_lines).toBe(1);
  });
});

import type { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { z } from "zod";
import {
  JanusUnifiedService,
  loadJanusConfig,
  loadClaude,
  MemoryClient,
  AssetRunner,
  RelBridge,
  type JanusConfig,
} from "@janus/integrations";
import { CommsService } from "../../janus-integrations/src/comms-service.js";
import type { CommsStatus } from "../../shared/src/comms.js";

export interface JanusMcpContext {
  janusRoot: string;
  config: JanusConfig;
  boundTaskId: string;
}

export function registerJanusMcpResources(
  server: McpServer,
  context: JanusMcpContext,
): void {
  const unified = new JanusUnifiedService(context.janusRoot, context.config);
  const memory = new MemoryClient(context.config.components.memory);
  const assets = new AssetRunner(context.janusRoot, context.config);
  const relBridge = new RelBridge(context.janusRoot, context.config);
  const comms = new CommsService(context.janusRoot);

  server.registerResource(
    "janus-doctrine-claude",
    "janus://doctrine/claude",
    {
      title: "CLAUDE.md — Janus single source of truth",
      description: "Operational doctrine, invariants, token policy, validation rules",
      mimeType: "text/markdown",
    },
    async () => {
      const claude = await loadClaude(context.janusRoot, context.config);
      return {
        contents: [
          {
            uri: "janus://doctrine/claude",
            mimeType: "text/markdown",
            text: claude,
          },
        ],
      };
    },
  );

  server.registerResource(
    "janus-system-status",
    "janus://system/status",
    {
      title: "Janus system status",
      description: "Unified health across orchestrator, memory, and asset engine",
      mimeType: "application/json",
    },
    async () => {
      const status = await unified.getSystemStatus();
      return {
        contents: [
          {
            uri: "janus://system/status",
            mimeType: "application/json",
            text: JSON.stringify(status, null, 2),
          },
        ],
      };
    },
  );

  server.registerResource(
    "janus-memory-health",
    "janus://memory/health",
    {
      title: "Memory service health",
      description: "Smart-Library API and Ollama availability",
      mimeType: "application/json",
    },
    async () => {
      const health = await memory.health();
      return {
        contents: [
          {
            uri: "janus://memory/health",
            mimeType: "application/json",
            text: JSON.stringify(health, null, 2),
          },
        ],
      };
    },
  );

  server.registerResource(
    "janus-assets-queue",
    "janus://assets/queue",
    {
      title: "Asset processing queue",
      description: "Omni32 mod queue status from AssetConverter",
      mimeType: "text/plain",
    },
    async () => {
      const queue = await assets.queue();
      return {
        contents: [
          {
            uri: "janus://assets/queue",
            mimeType: "text/plain",
            text: queue.raw,
          },
        ],
      };
    },
  );

  if (context.config.components.cognition) {
    server.registerResource(
      "janus-rel-state-summary",
      "janus://rel/state-summary",
      {
        title: "REL cognition state summary",
        description: "Current REL cognitive state when cognition bridge is configured",
        mimeType: "application/json",
      },
      async () => {
        const status = await relBridge.getStatus();
        return {
          contents: [
            {
              uri: "janus://rel/state-summary",
              mimeType: "application/json",
              text: JSON.stringify(status, null, 2),
            },
          ],
        };
      },
    );
  }

  server.registerResource(
    "janus-task-brief",
    `janus://task/${context.boundTaskId}/brief`,
    {
      title: "Token-efficient executor brief",
      description: "Unified brief with memory context slices for the bound task",
      mimeType: "application/json",
    },
    async () => {
      const brief = await unified.buildUnifiedBrief(context.boundTaskId);
      return {
        contents: [
          {
            uri: `janus://task/${context.boundTaskId}/brief`,
            mimeType: "application/json",
            text: JSON.stringify(brief, null, 2),
          },
        ],
      };
    },
  );

  server.registerResource(
    "janus-task-repair",
    `janus://task/${context.boundTaskId}/repair`,
    {
      title: "Repair context",
      description: "Validation errors plus memory-retrieved fix patterns",
      mimeType: "application/json",
    },
    async () => {
      const repair = await unified.buildRepairContext(context.boundTaskId);
      return {
        contents: [
          {
            uri: `janus://task/${context.boundTaskId}/repair`,
            mimeType: "application/json",
            text: JSON.stringify(repair, null, 2),
          },
        ],
      };
    },
  );

  server.registerTool(
    "janus-memory-query",
    {
      description: "Semantic query against Smart-Library memory store",
      inputSchema: {
        query: z.string().min(1),
      },
    },
    async ({ query }) => {
      try {
        const result = await memory.query(query);
        return {
          content: [{ type: "text", text: JSON.stringify(result, null, 2) }],
        };
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        return {
          content: [{ type: "text", text: message }],
          isError: true,
        };
      }
    },
  );

  server.registerTool(
    "janus-repair-context",
    {
      description: "Build repair context for the bound task from validation errors and memory",
      inputSchema: {
        task_id: z.string().optional(),
      },
    },
    async ({ task_id }) => {
      if (task_id && task_id !== context.boundTaskId) {
        return {
          content: [
            {
              type: "text",
              text: `Task scope violation: server is bound to ${context.boundTaskId}`,
            },
          ],
          isError: true,
        };
      }

      try {
        const repair = await unified.buildRepairContext(context.boundTaskId);
        return {
          content: [{ type: "text", text: JSON.stringify(repair, null, 2) }],
        };
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        return {
          content: [{ type: "text", text: message }],
          isError: true,
        };
      }
    },
  );

  server.registerTool(
    "janus-comms-post",
    {
      description: "Append a message to the append-only comms JSONL store at .aether/comms.jsonl and mirror to COMMS-CLAUDE-GROK.md",
      inputSchema: {
        author: z.string().min(1),
        recipient: z.string().min(1),
        task_id: z.string().optional(),
        status: z.enum(["INFO", "ASK", "BLOCKED", "HANDOFF", "DONE"]),
        body: z.string().min(1),
      },
    },
    async (input) => {
      try {
        const postInput = {
          author: input.author,
          recipient: input.recipient,
          task_id: input.task_id,
          status: input.status as "INFO" | "ASK" | "BLOCKED" | "HANDOFF" | "DONE",
          body: input.body,
        };
        const result = await comms.post(postInput);
        return {
          content: [{ type: "text", text: JSON.stringify(result, null, 2) }],
        };
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        return {
          content: [{ type: "text", text: message }],
          isError: true,
        };
      }
    },
  );

  server.registerTool(
    "janus-comms-read",
    {
      description: "Read recent messages from .aether/comms.jsonl, filterable by task_id and since (ISO timestamp)",
      inputSchema: {
        task_id: z.string().optional(),
        since: z.string().datetime().optional(),
        limit: z.coerce.number().int().min(1).max(500).optional(),
      },
    },
    async (filter) => {
      try {
        const result = await comms.read({
          task_id: filter.task_id,
          since: filter.since,
          limit: filter.limit,
        });
        return {
          content: [{ type: "text", text: JSON.stringify(result, null, 2) }],
        };
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        return {
          content: [{ type: "text", text: message }],
          isError: true,
        };
      }
    },
  );
}

export async function resolveJanusRoot(startDir: string): Promise<string | null> {
  try {
    const { root } = await loadJanusConfig(startDir);
    return root;
  } catch {
    return null;
  }
}

import { readFile } from "node:fs/promises";
import { Command } from "commander";
import { AssigneeSchema, PatchProposalSchema, TaskStatusSchema } from "@aether/shared";
import { ContextResolver } from "@aether/context";
import { TaskQueue } from "@aether/task-queue";
import { HandoffService } from "@aether/validation-kernel";
import { resolveTaskWorkspace, setupJdtls, WorkloadManager } from "@aether/workload-manager";
import {
  prepareWorktreeDependencies,
  WorktreeManager,
  type CreateWorktreeOptions,
} from "@aether/worktree-manager";
import { OrchestratorService, type DelegationPlan } from "@aether/orchestrator";
import { JanusUnifiedService, loadJanusConfig } from "@janus/integrations";
import { CommsService } from "../../janus-integrations/src/comms-service.js";
import { findRepoRoot } from "./repo.js";
import { registerJanusCommands } from "./janus-commands.js";

interface TaskCreateFile {
  parent_id?: string | null;
  worktree?: string | null;
  workload?: string | null;
  assignee?: "grok" | "claude" | null;
  context_refs?: string[];
  validation_profile: string;
  spec: {
    objective: string;
    constraints: string[];
    files_in_scope: string[];
    acceptance_criteria: string[];
  };
}

export function buildProgram(cliName: "janus" | "aether" = "aether"): Command {
  const program = new Command();

  if (cliName === "janus") {
    program
      .name("janus")
      .description("JanusPrime CLI — unified autonomous development and asset generation")
      .version("0.4.0");
  } else {
    program
      .name("aether")
      .description("Aether CLI — task queue, validation gate, worktrees, and Phase 1 orchestration")
      .version("0.4.0");
  }

  const task = program.command("task").description("Manage structured tasks");

  task
    .command("create")
    .description("Create a task from a JSON file")
    .requiredOption("-f, --file <path>", "Task definition JSON file")
    .action(async (options: { file: string }) => {
      const repoRoot = await findRepoRoot(process.cwd());
      const queue = new TaskQueue(repoRoot);
      const raw = await readFile(options.file, "utf8");
      const parsed = JSON.parse(raw) as TaskCreateFile;
      const created = await queue.create({
        ...parsed,
        context_refs: parsed.context_refs ?? [],
      });
      console.log(JSON.stringify(created, null, 2));
    });

  task
    .command("list")
    .description("List all tasks")
    .action(async () => {
      const repoRoot = await findRepoRoot(process.cwd());
      const queue = new TaskQueue(repoRoot);
      const tasks = await queue.list();
      console.log(JSON.stringify(tasks, null, 2));
    });

  task
    .command("show")
    .description("Show a single task")
    .argument("<taskId>", "Task identifier")
    .action(async (taskId: string) => {
      const repoRoot = await findRepoRoot(process.cwd());
      const queue = new TaskQueue(repoRoot);
      const entry = await queue.get(taskId);
      console.log(JSON.stringify(entry, null, 2));
    });

  task
    .command("assign")
    .description("Assign a task to grok or claude")
    .argument("<taskId>", "Task identifier")
    .requiredOption("-a, --assignee <name>", "grok or claude")
    .action(async (taskId: string, options: { assignee: string }) => {
      const repoRoot = await findRepoRoot(process.cwd());
      const queue = new TaskQueue(repoRoot);
      const assignee = AssigneeSchema.parse(options.assignee);
      const updated = await queue.assign(taskId, assignee);
      console.log(JSON.stringify(updated, null, 2));
    });

  task
    .command("status")
    .description("Transition task status")
    .argument("<taskId>", "Task identifier")
    .requiredOption("-s, --status <status>", "Target status")
    .action(async (taskId: string, options: { status: string }) => {
      const repoRoot = await findRepoRoot(process.cwd());
      const queue = new TaskQueue(repoRoot);
      const status = TaskStatusSchema.parse(options.status);
      const updated = await queue.transition(taskId, status);
      console.log(JSON.stringify(updated, null, 2));
    });

  const worktree = program.command("worktree").description("Manage git worktrees");

  worktree
    .command("create")
    .description("Create an isolated worktree for a task")
    .requiredOption("-t, --task <taskId>", "Task identifier")
    .option("-b, --base <branch>", "Base branch")
    .option("-w, --workload <id>", "Workload whose cloned repo owns the worktree")
    .option("--recreate", "Tear down any existing worktree/branch and rebuild from base", false)
    .action(
      async (options: {
        task: string;
        base?: string;
        workload?: string;
        recreate?: boolean;
      }) => {
        const repoRoot = await findRepoRoot(process.cwd());
        const queue = new TaskQueue(repoRoot);

        const createOptions = buildCreateWorktreeOptions(
          options.task,
          options.base,
          options.recreate,
        );

        const created = options.workload
          ? await new WorkloadManager(repoRoot).createWorktree(options.workload, createOptions)
          : await new WorktreeManager(repoRoot).create({
              ...createOptions,
              baseBranch: createOptions.baseBranch ?? "main",
            });

        const updated = await queue.setWorktree(
          options.task,
          created.name,
          options.workload ?? null,
        );
        console.log(JSON.stringify({ worktree: created, task: updated }, null, 2));
      },
    );

  worktree
    .command("list")
    .description("List Aether-managed worktrees")
    .option("-w, --workload <id>", "List worktrees for a workload repository")
    .action(async (options: { workload?: string }) => {
      const repoRoot = await findRepoRoot(process.cwd());

      const entries = options.workload
        ? await new WorkloadManager(repoRoot).listWorktrees(options.workload)
        : await new WorktreeManager(repoRoot).list();

      console.log(JSON.stringify(entries, null, 2));
    });

  worktree
    .command("prepare")
    .description("Install dependencies in a task worktree")
    .requiredOption("-t, --task <taskId>", "Task identifier")
    .action(async (options: { task: string }) => {
      const repoRoot = await findRepoRoot(process.cwd());
      const queue = new TaskQueue(repoRoot);
      const task = await queue.get(options.task);

      if (!task.worktree) {
        throw new Error(`Task ${task.id} has no worktree`);
      }

      const workspaceRoot = await resolveTaskWorkspaceForCli(repoRoot, task);
      const result = await prepareWorktreeDependencies(workspaceRoot);
      console.log(JSON.stringify(result, null, 2));
    });

  worktree
    .command("destroy")
    .description("Remove worktree and branch for a task")
    .requiredOption("-t, --task <taskId>", "Task identifier")
    .action(async (options: { task: string }) => {
      const repoRoot = await findRepoRoot(process.cwd());
      const queue = new TaskQueue(repoRoot);
      const task = await queue.get(options.task);

      if (task.workload) {
        await new WorkloadManager(repoRoot).destroyWorktree(task.workload, options.task);
      } else {
        await new WorktreeManager(repoRoot).destroy(options.task);
      }

      const updated = await queue.setWorktree(options.task, null);
      console.log(JSON.stringify(updated, null, 2));
    });

  const setup = program.command("setup").description("Bootstrap Aether dependencies");

  setup
    .command("jdtls")
    .description("Download and configure Eclipse JDT.LS for Java validation")
    .option("--java <path>", "Java executable path", "java")
    .action(async (options: { java: string }) => {
      const repoRoot = await findRepoRoot(process.cwd());
      const result = await setupJdtls(repoRoot, options.java);
      console.log(JSON.stringify(result, null, 2));
    });

  const workload = program.command("workload").description("Manage external workload repositories");

  workload
    .command("init")
    .description("Create a workload manifest")
    .argument("<id>", "Workload identifier")
    .requiredOption("-d, --description <text>", "Workload description")
    .option("--url <repository>", "Git repository URL")
    .option("-b, --branch <branch>", "Default branch", "main")
    .option("-p, --profile <id>", "Validation profile", "neoforge-mixin-v1")
    .action(async (id: string, options: { description: string; url?: string; branch: string; profile: string }) => {
      const repoRoot = await findRepoRoot(process.cwd());
      const manager = new WorkloadManager(repoRoot);
      const manifest = await manager.init({
        id,
        description: options.description,
        repository: options.url ?? null,
        branch: options.branch,
        validation_profile: options.profile,
      });
      console.log(JSON.stringify(manifest, null, 2));
    });

  workload
    .command("set-url")
    .description("Set or update workload repository URL")
    .argument("<id>", "Workload identifier")
    .requiredOption("--url <repository>", "Git repository URL")
    .option("-b, --branch <branch>", "Default branch", "main")
    .action(async (id: string, options: { url: string; branch: string }) => {
      const repoRoot = await findRepoRoot(process.cwd());
      const manager = new WorkloadManager(repoRoot);
      const manifest = await manager.setRepository(id, options.url, options.branch);
      console.log(JSON.stringify(manifest, null, 2));
    });

  workload
    .command("list")
    .description("List workload manifests")
    .action(async () => {
      const repoRoot = await findRepoRoot(process.cwd());
      const manager = new WorkloadManager(repoRoot);
      const manifests = await manager.list();
      console.log(JSON.stringify(manifests, null, 2));
    });

  workload
    .command("clone")
    .description("Clone or update a workload repository")
    .argument("<id>", "Workload identifier")
    .action(async (id: string) => {
      const repoRoot = await findRepoRoot(process.cwd());
      const manager = new WorkloadManager(repoRoot);
      const result = await manager.clone(id);
      console.log(JSON.stringify(result, null, 2));
    });

  const workloadWorktree = workload
    .command("worktree")
    .description("Manage git worktrees inside a workload repository");

  workloadWorktree
    .command("create")
    .description("Create an isolated worktree for a task in a workload repo")
    .argument("<id>", "Workload identifier")
    .requiredOption("-t, --task <taskId>", "Task identifier")
    .option("-b, --base <branch>", "Base branch")
    .action(async (id: string, options: { task: string; base?: string }) => {
      const repoRoot = await findRepoRoot(process.cwd());
      const manager = new WorkloadManager(repoRoot);
      const queue = new TaskQueue(repoRoot);

      const created = await manager.createWorktree(
        id,
        buildCreateWorktreeOptions(options.task, options.base),
      );

      const updated = await queue.setWorktree(options.task, created.name, id);
      console.log(JSON.stringify({ worktree: created, task: updated }, null, 2));
    });

  workloadWorktree
    .command("list")
    .description("List Aether-managed worktrees for a workload repository")
    .argument("<id>", "Workload identifier")
    .action(async (id: string) => {
      const repoRoot = await findRepoRoot(process.cwd());
      const manager = new WorkloadManager(repoRoot);
      const entries = await manager.listWorktrees(id);
      console.log(JSON.stringify(entries, null, 2));
    });

  workloadWorktree
    .command("destroy")
    .description("Remove worktree and branch for a task in a workload repository")
    .argument("<id>", "Workload identifier")
    .requiredOption("-t, --task <taskId>", "Task identifier")
    .action(async (id: string, options: { task: string }) => {
      const repoRoot = await findRepoRoot(process.cwd());
      const manager = new WorkloadManager(repoRoot);
      const queue = new TaskQueue(repoRoot);

      await manager.destroyWorktree(id, options.task);
      const updated = await queue.setWorktree(options.task, null);
      console.log(JSON.stringify(updated, null, 2));
    });

  const context = program.command("context").description("Resolve task context references");

  context
    .command("resolve")
    .description("Resolve context refs to markdown documents")
    .option("-t, --task <taskId>", "Resolve refs from a task")
    .option("-r, --refs <refs>", "Comma-separated context refs")
    .action(async (options: { task?: string; refs?: string }) => {
      const repoRoot = await findRepoRoot(process.cwd());
      const resolver = new ContextResolver(repoRoot);

      let refs: string[] = [];
      if (options.task) {
        const queue = new TaskQueue(repoRoot);
        const task = await queue.get(options.task);
        refs = task.context_refs;
      } else if (options.refs) {
        refs = options.refs.split(",").map((ref) => ref.trim()).filter((ref) => ref.length > 0);
      } else {
        throw new Error("Provide --task or --refs");
      }

      const bundle = await resolver.resolve(refs);
      console.log(JSON.stringify(bundle, null, 2));
    });

  context
    .command("catalog")
    .description("List known context references")
    .action(async () => {
      const repoRoot = await findRepoRoot(process.cwd());
      const resolver = new ContextResolver(repoRoot);
      console.log(JSON.stringify(resolver.listCatalog(), null, 2));
    });

  const patch = program.command("patch").description("Submit and apply validated patches");

  patch
    .command("submit")
    .description("Validate a patch proposal against the task worktree")
    .requiredOption("-f, --file <path>", "Patch proposal JSON file")
    .option("--apply", "Persist patch when validation passes", false)
    .action(async (options: { file: string; apply: boolean }) => {
      const repoRoot = await findRepoRoot(process.cwd());
      const raw = await readFile(options.file, "utf8");
      const proposal = PatchProposalSchema.parse(JSON.parse(raw) as unknown);
      const handoff = new HandoffService(repoRoot);
      const result = await handoff.submit({
        repoRoot,
        proposal,
        apply: options.apply,
      });

      console.log(
        JSON.stringify(
          {
            applied: result.applied,
            task: result.task,
            validation: result.validation,
          },
          null,
          2,
        ),
      );

      if (!result.validation.passed) {
        process.exitCode = 1;
      }
    });

  patch
    .command("apply")
    .description("Apply a patch that already has a passing validation receipt")
    .requiredOption("-f, --file <path>", "Patch proposal JSON file")
    .action(async (options: { file: string }) => {
      const repoRoot = await findRepoRoot(process.cwd());
      const raw = await readFile(options.file, "utf8");
      const proposal = PatchProposalSchema.parse(JSON.parse(raw) as unknown);
      const handoff = new HandoffService(repoRoot);
      const task = await handoff.applyValidatedPatch(repoRoot, proposal);
      console.log(JSON.stringify(task, null, 2));
    });

  const orchestrate = program
    .command("orchestrate")
    .description("Phase 1 orchestration — delegation plans and child rollups");

  orchestrate
    .command("plan")
    .description("Create parent and child tasks from a delegation plan JSON file")
    .requiredOption("-f, --file <path>", "Delegation plan JSON file")
    .action(async (options: { file: string }) => {
      const repoRoot = await findRepoRoot(process.cwd());
      const raw = await readFile(options.file, "utf8");
      const plan = JSON.parse(raw) as unknown;
      const orchestrator = new OrchestratorService(repoRoot);
      const result = await orchestrator.createPlan(plan as DelegationPlan);
      console.log(JSON.stringify(result, null, 2));
    });

  orchestrate
    .command("status")
    .description("Roll up child task statuses for a parent task")
    .requiredOption("-t, --task <parentId>", "Parent task identifier")
    .action(async (options: { task: string }) => {
      const repoRoot = await findRepoRoot(process.cwd());
      const orchestrator = new OrchestratorService(repoRoot);
      const rollup = await orchestrator.rollupStatus(options.task);
      console.log(JSON.stringify(rollup, null, 2));

      if (!rollup.complete) {
        process.exitCode = 1;
      }
    });

  orchestrate
    .command("provision")
    .description("Provision worktrees for all children missing worktrees")
    .requiredOption("-t, --task <parentId>", "Parent task identifier")
    .action(async (options: { task: string }) => {
      const repoRoot = await findRepoRoot(process.cwd());
      const orchestrator = new OrchestratorService(repoRoot);
      const provisioned = await orchestrator.provisionChildren(options.task);
      console.log(JSON.stringify(provisioned, null, 2));
    });

  orchestrate
    .command("run")
    .description("Run identity-patch children through the validation gate")
    .requiredOption("-t, --task <parentId>", "Parent task identifier")
    .action(async (options: { task: string }) => {
      const repoRoot = await findRepoRoot(process.cwd());
      const orchestrator = new OrchestratorService(repoRoot);
      const results = await orchestrator.runChildren(options.task);
      const rollup = await orchestrator.rollupStatus(options.task);
      console.log(JSON.stringify({ results, rollup }, null, 2));

      if (!rollup.complete) {
        process.exitCode = 1;
      }
    });

  const execute = program
    .command("execute")
    .description("Grok executor surface — scoped briefs and identity patches");

  execute
    .command("brief")
    .description("Build minimal executor brief JSON for a task")
    .requiredOption("-t, --task <taskId>", "Task identifier")
    .action(async (options: { task: string }) => {
      try {
        const { root, config } = await loadJanusConfig(process.cwd());
        const unified = new JanusUnifiedService(root, config);
        const brief = await unified.buildUnifiedBrief(options.task);
        console.log(JSON.stringify(brief, null, 2));
      } catch {
        const repoRoot = await findRepoRoot(process.cwd());
        const orchestrator = new OrchestratorService(repoRoot);
        const brief = await orchestrator.buildExecutorBrief(options.task);
        console.log(JSON.stringify(brief, null, 2));
      }
    });

  execute
    .command("identity-patch")
    .description("Build identity patch proposal JSON (no submit)")
    .requiredOption("-t, --task <taskId>", "Task identifier")
    .action(async (options: { task: string }) => {
      const repoRoot = await findRepoRoot(process.cwd());
      const orchestrator = new OrchestratorService(repoRoot);
      const proposal = await orchestrator.buildIdentityPatch(options.task);
      console.log(JSON.stringify(proposal, null, 2));
    });

  execute
    .command("run")
    .description("Execute an identity-patch task through the validation gate")
    .requiredOption("-t, --task <taskId>", "Task identifier")
    .action(async (options: { task: string }) => {
      const repoRoot = await findRepoRoot(process.cwd());
      const orchestrator = new OrchestratorService(repoRoot);
      const result = await orchestrator.executeIdentityTask(options.task);
      console.log(JSON.stringify(result, null, 2));

      if (result.task.status !== "accepted" || !result.validation.passed) {
        process.exitCode = 1;
      }
    });

  registerJanusCommands(program);

  const janus = program.commands.find((c) => c.name() === "janus") as Command | undefined;
  if (janus) {
    const comms = janus
      .command("comms")
      .description("MCP comms channel backed by append-only .aether/comms.jsonl mirrored to COMMS-CLAUDE-GROK.md");

    comms
      .command("post")
      .description("Post a message (appends to JSONL and mirrors to markdown)")
      .requiredOption("--author <name>", "Author (e.g. Grok or Claude)")
      .requiredOption("--recipient <name>", "Recipient")
      .option("-t, --task <taskId>", "Associated task id")
      .requiredOption("--status <status>", "INFO | ASK | BLOCKED | HANDOFF | DONE")
      .requiredOption("--body <text>", "Message body")
      .action(async (opts: { author: string; recipient: string; task?: string; status: string; body: string }) => {
        const { root } = await loadJanusConfig(process.cwd());
        const svc = new CommsService(root);
        const res = await svc.post({
          author: opts.author,
          recipient: opts.recipient,
          task_id: opts.task,
          status: opts.status as "INFO" | "ASK" | "BLOCKED" | "HANDOFF" | "DONE",
          body: opts.body,
        });
        console.log(JSON.stringify(res, null, 2));
      });

    comms
      .command("read")
      .description("Read recent messages, optionally filtered by task_id and since")
      .option("-t, --task <taskId>", "Filter to task_id")
      .option("--since <isoTs>", "ISO-8601 lower bound (inclusive)")
      .option("--limit <n>", "Max messages to return", "100")
      .action(async (opts: { task?: string; since?: string; limit?: string }) => {
        const { root } = await loadJanusConfig(process.cwd());
        const svc = new CommsService(root);
        const res = await svc.read({
          task_id: opts.task,
          since: opts.since,
          limit: opts.limit ? Number.parseInt(opts.limit, 10) : undefined,
        });
        console.log(JSON.stringify(res, null, 2));
      });
  }

  return program;
}

async function resolveTaskWorkspaceForCli(
  repoRoot: string,
  task: Awaited<ReturnType<TaskQueue["get"]>>,
): Promise<string> {
  return resolveTaskWorkspace(repoRoot, task);
}

function buildCreateWorktreeOptions(
  taskId: string,
  baseBranch?: string,
  recreate?: boolean,
): CreateWorktreeOptions {
  const options: CreateWorktreeOptions = { taskId };
  if (baseBranch !== undefined) {
    options.baseBranch = baseBranch;
  }
  if (recreate) {
    options.recreate = true;
  }
  return options;
}
